"""Local compare-and-swap snapshot store. No remote actions or implicit recovery."""

import json
import os
import tempfile
from contextlib import contextmanager
from pathlib import Path

from .codec import Document, PixlError, Record, Ref, Symbol, digest, encode, parse
from .graph import closure, edges, proof_scope, validate

TRANSITIONS = {
    "open": {"active", "blocked", "dropped"},
    "active": {"blocked", "done", "dropped"},
    "blocked": {"open", "active", "dropped"},
    "done": {"open"},
    "dropped": {"open"},
}
JOB_TRANSITIONS = {
    "prepared": {"submitted", "unknown", "failed"},
    "submitted": {"running", "succeeded", "failed", "unknown"},
    "running": {"succeeded", "failed", "unknown"},
    "unknown": {"submitted", "running", "succeeded", "failed"},
    "succeeded": set(),
    "failed": set(),
}


@contextmanager
def lock(folder):
    folder = Path(folder).resolve()
    folder.mkdir(parents=True, exist_ok=True)
    path = folder / ".lock"
    try:
        fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    except FileExistsError as error:
        raise PixlError(
            "store_locked",
            f"{path}; inspect owner PID and ensure no writer remains before removing a stale lock",
        ) from error
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            json.dump({"pid": os.getpid()}, stream)
            stream.flush()
            os.fsync(stream.fileno())
        yield
    finally:
        path.unlink(missing_ok=True)


def _atomic(path, data):
    path = Path(path)
    fd, temp = tempfile.mkstemp(prefix=".pixl-write-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp, path)
    finally:
        Path(temp).unlink(missing_ok=True)


def _publish(folder, doc):
    data, hash_ = encode(doc), digest(doc)
    history = folder / "history"
    if history.is_symlink() or not history.resolve().is_relative_to(folder):
        raise PixlError("store_path", "history must remain inside the store")
    history.mkdir(exist_ok=True)
    snapshot = history / f"{hash_}.px"
    if snapshot.is_symlink() or not snapshot.resolve().is_relative_to(folder):
        raise PixlError("store_path", "snapshot must remain inside the store")
    if snapshot.exists():
        if snapshot.read_bytes() != data:
            raise PixlError("history_corrupt", str(snapshot))
    else:
        _atomic(snapshot, data)
    _atomic(folder / "state.px", data)
    return {"revision": doc.revision, "hash": hash_, "state": str(folder / "state.px")}


def empty_project(name="PIXL project"):
    actor = Record("actor", "A", {"nm": "PIXL", "rl": Symbol("agent")})
    contract = Record(
        "contract",
        "C",
        {
            "nm": "unconfirmed-intake",
            "px": [32, 32],
            "pl": [],
            "vw": Symbol("side"),
            "sa": Symbol("nearest"),
            "al": Symbol("binary"),
            "li": "INTAKE DEFAULTS ONLY: replace with source-grounded project intent before generation",
        },
    )
    project = Record(
        "project",
        "P",
        {"nm": name, "ow": Ref("actor"), "ct": Ref("contract"), "sc": []},
    )
    return Document(0, {r.id: r for r in (actor, contract, project)})


def intake_project(name="PIXL project", brief=""):
    actor = Record("actor", "A", {"nm": "PIXL", "rl": Symbol("agent")})
    user = Record("user", "A", {"nm": "Project owner", "rl": Symbol("user")})
    project = Record(
        "project", "P", {"nm": name, "ow": Ref("user"), "sc": [], "in": [], "br": brief}
    )
    return Document(0, {r.id: r for r in (actor, user, project)}, format=2)


def initialize(folder, doc=None, root=None, name="PIXL project"):
    folder = Path(folder).resolve()
    doc = empty_project(name) if doc is None else doc
    with lock(folder):
        if (folder / "state.px").exists():
            raise PixlError("store_exists", str(folder))
        if doc.revision != 0:
            raise PixlError("revision", "initial state must be revision 0")
        validate(doc, root if root is not None else folder.parent)
        _acceptance_plan(None, doc)
        from . import delivery, jobs

        jobs.transitions(None, doc, root if root is not None else folder.parent, folder)
        delivery.transitions(None, doc, root if root is not None else folder.parent, folder)
        return _publish(folder, doc)


def load(folder):
    path = Path(folder) / "state.px"
    try:
        return parse(path.read_bytes())
    except OSError as error:
        raise PixlError("store_read", str(path)) from error


def _acceptance_plan(current, candidate):
    """Require a saved, unchanged acceptance plan before recording evaluation.

    Called only after full candidate validation, so traversal cannot dereference
    malformed candidate references. This checks recorded order, not human honesty.
    """
    if candidate.format != 2:
        return
    for id_, record in candidate.records.items():
        if record.kind != "V":
            continue
        if current is not None and id_ in current.records:
            continue
        if record.fields.get("ob", False):
            raise PixlError(
                "verdict_history",
                f"{id_}: a new verdict must be validated before later supersession",
            )
        if record.fields["st"].value == "unavailable":
            continue
        artifact = candidate.records[record.fields["xr"].id]
        output = artifact.fields["of"].id
        if current is None or output not in current.records:
            raise PixlError(
                "acceptance_plan",
                f"{id_}: save the output and criteria before recording evaluation",
            )
        planned = proof_scope(candidate, [output])
        if planned != proof_scope(current, [output]) or any(
            candidate.records[target] != current.records.get(target)
            for target in planned
        ):
            raise PixlError(
                "acceptance_plan",
                f"{id_}: acceptance plan changed; save it before new evaluation",
            )


def _transitions(current, candidate):
    if current.format != candidate.format:
        raise PixlError(
            "format_change",
            "store format cannot change implicitly; create an explicitly authored new project",
        )
    adjacency = edges(current)
    if current.format == 2:
        adjacency = {
            id_: {target for target in targets if current.records[target].kind != "P"}
            for id_, targets in adjacency.items()
        }
    for id_, old in current.records.items():
        new = candidate.records.get(id_)
        if (
            old.kind == "T"
            and old.fields["st"].value == "done"
            and new is not None
            and new.fields.get("st") == Symbol("done")
        ):
            for dependency in closure(adjacency, [id_]):
                if current.records[dependency] != candidate.records.get(dependency):
                    raise PixlError(
                        "reopen_required", f"{id_}: dependency {dependency} changed"
                    )
    for id_, old in current.records.items():
        if id_ not in candidate.records:
            raise PixlError("record_removal", id_)
        new = candidate.records[id_]
        if old.kind != new.kind:
            raise PixlError("record_kind_change", id_)
        if old.kind == "E" or (current.format == 2 and old.kind == "V"):
            old_fields = {k: v for k, v in old.fields.items() if k != "ob"}
            new_fields = {k: v for k, v in new.fields.items() if k != "ob"}
            if old_fields != new_fields or (
                old.fields.get("ob", False) and not new.fields.get("ob", False)
            ):
                code = "evidence_immutable" if old.kind == "E" else "verdict_immutable"
                raise PixlError(
                    code, f"{id_}: supersede with ob=+ and add a new record ID"
                )
        if old.kind in ("T", "J"):
            field, transitions = (
                ("st", TRANSITIONS) if old.kind == "T" else ("si", JOB_TRANSITIONS)
            )
            before, after = old.fields[field], new.fields.get(field)
            if not isinstance(after, Symbol):
                raise PixlError("transition", f"{id_}: missing state")
            if before != after and after.value not in transitions[before.value]:
                raise PixlError("transition", f"{id_}: {before.value} -> {after.value}")
            if (
                old.kind == "T"
                and before.value == "done"
                and after.value == "done"
                and old != new
            ):
                raise PixlError("reopen_required", id_)
            if old.kind == "J":
                for key in ("tk", "tl", "ah"):
                    if old.fields[key] != new.fields.get(key):
                        raise PixlError("job_intent_change", f"{id_}.{key}")
                if old.fields["ri"] and old.fields["ri"] != new.fields.get("ri"):
                    raise PixlError("job_identity_change", id_)


def commit(folder, candidate, expected, root=None):
    folder = Path(folder).resolve()
    with lock(folder):
        current = load(folder)
        validate(
            current
        )  # Drift in files can be repaired by a correctly grounded candidate.
        if digest(current) != expected:
            raise PixlError(
                "stale_write",
                "reload state and recompute the candidate from the current revision",
            )
        if candidate.revision != current.revision + 1:
            raise PixlError("revision", f"expected {current.revision + 1}")
        _transitions(current, candidate)
        validate(candidate, root if root is not None else folder.parent)
        _acceptance_plan(current, candidate)
        from . import delivery, jobs

        jobs.transitions(current, candidate, root if root is not None else folder.parent, folder)
        delivery.transitions(current, candidate, root if root is not None else folder.parent, folder)
        return _publish(folder, candidate)

"""PX2 intake, planned outputs, candidate acceptance and read-only readiness.

The graph module owns wire/schema, reference, file and evidence-hash validation.
This module runs after those checks. Reports consume an already validated graph
and never create evidence, advance tasks or recursively invoke validation.
"""

from datetime import datetime

from .codec import PixlError, encode_value, to_data

NONRASTER = {"code", "report", "reference"}
CONTRACT_FIELDS = {"nm", "px", "pl", "vw", "sa", "al", "li", "ch", "tg"}
ADOPTION_PHASES = {"production", "delivery"}


def _require(condition, code, detail):
    if not condition:
        raise PixlError(code, detail)


def _ids(references):
    return {reference.id for reference in references}


def _unique(references, code, detail):
    _require(len(_ids(references)) == len(references), code, detail)


def _output_choices(doc, task):
    """Only output contracts impose a task's own project/style obligations.

    A source input may intentionally belong to another project or contract.
    Unrelated project choices also do not gate research or accepted samples.
    """
    choices = set()
    for output in task["op"]:
        contract = doc.records[output.id].fields.get("ct")
        if contract is not None:
            choices.update(_ids(doc.records[contract.id].fields.get("ch", [])))
    return choices


def _activation_blockers(doc, task_id, scope, bound):
    from . import families

    task = doc.records[task_id].fields
    reasons = []
    for dependency in task["dp"]:
        state = doc.records[dependency.id].fields["st"].value
        if state != "done":
            reasons.append(f"task_prerequisite: {dependency.id} is {state}; it must be done")
    for reference in task["op"]:
        output = doc.records[reference.id].fields
        if output["kd"].value not in NONRASTER and "ct" not in output:
            reasons.append(f"output_contract: {reference.id} needs a concrete raster contract")
    choice_ids = sorted(_output_choices(doc, task))
    for choice_id in choice_ids:
        choice = doc.records[choice_id].fields
        state = choice["st"].value
        if state in {"unresolved", "conflict"}:
            reasons.append(
                f"choice_{state}: {choice_id} ({choice['ky']}) is {state}; resolve it before active work"
            )
    if task["ph"].value in ADOPTION_PHASES:
        if not task["dc"]:
            reasons.append(f"task_decision: {task_id} needs an evidence-backed adoption decision")
        for reference in task["kn"]:
            method = doc.records[reference.id].fields
            if not scope(reference.id) <= bound(method.get("pc", []), passing=True):
                reasons.append(f"method_poc: {reference.id} needs current passing method proof")
        for choice_id in choice_ids:
            choice = doc.records[choice_id].fields
            if choice["st"].value in {"observed", "proposed"}:
                reasons.append(f"choice_unconfirmed: {choice_id} ({choice['ky']}) must be confirmed")
    reasons.extend(families.blockers(doc, task_id))
    return reasons


def validate(doc, scope, bound):
    """Validate PX2 semantics after the graph's shared checks.

    ``scope(id)`` returns the semantic proof closure. ``bound(refs, passing)``
    returns IDs bound by current receipts. Both are supplied by graph.validate
    so lifecycle checks use precisely the same evidence interpretation.
    """
    choice_keys = set()
    current_verdicts = {}

    for id_, record in doc.records.items():
        f = record.fields
        if record.kind == "P":
            _unique(f["in"], "intake_project", f"{id_}.in repeats a choice")
            for choice in f["in"]:
                _require(
                    doc.records[choice.id].fields["pr"].id == id_,
                    "intake_project", f"{id_}.in includes another project's choice {choice.id}",
                )
        elif record.kind == "I":
            project_id = f["pr"].id
            _require(
                id_ in _ids(doc.records[project_id].fields["in"]),
                "intake_project", f"{id_} must be listed in {project_id}.in",
            )
            key = (project_id, f["ky"])
            _require(
                bool(f["ky"].strip()) and key not in choice_keys,
                "intake_key", f"{id_}: choice keys must be nonempty and unique within a project",
            )
            choice_keys.add(key)
            state, value = f["st"].value, f["vl"]
            if state == "unresolved":
                _require(value is None, "intake_value", f"{id_}: unresolved value must be null")
            elif state == "conflict":
                _require(
                    isinstance(value, list) and len(value) >= 2,
                    "intake_value", f"{id_}: conflict needs at least two alternatives",
                )
            else:
                _require(value is not None, "intake_value", f"{id_}: {state} value cannot be null")
            if state in {"observed", "confirmed"}:
                _require(bool(f["so"]), "intake_source", f"{id_}: {state} choice needs sources")
            if state == "proposed":
                _require(bool(f["wy"].strip()), "intake_rationale", f"{id_}: proposal needs a rationale")
        elif record.kind == "C":
            _unique(f.get("ch", []), "contract_choice", f"{id_}.ch repeats a choice")
            for reference in f.get("ch", []):
                choice = doc.records[reference.id].fields
                # Retain the last interpretation while an open/blocked task
                # resolves changed intent. Activation is gated separately.
                if choice["st"].value in {"unresolved", "conflict"}:
                    continue
                key = choice["ky"]
                if key in CONTRACT_FIELDS:
                    _require(
                        key in f and encode_value(choice["vl"]) == encode_value(f[key]),
                        "contract_choice", f"{id_}.{key} does not equal choice {reference.id}",
                    )
        elif record.kind == "F":
            owner = doc.records[f["tk"].id].fields
            _require(id_ in _ids(owner["op"]), "output_owner", f"{id_} must be listed by its owning task")
            _require(bool(f["rq"]), "output_requirements", f"{id_} needs at least one acceptance criterion")
            _unique(f["rq"], "output_requirements", f"{id_}.rq repeats a criterion")
        elif record.kind == "Q":
            _require(bool(f["ck"].strip()), "criterion_check", f"{id_} needs an observable check")
            required_mode = {"visual": "visual", "engine": "live"}.get(f["dm"].value)
            _require(
                required_mode is None or f["md"].value == required_mode,
                "criterion_mode", f"{id_}: {f['dm'].value} requires {required_mode} evidence",
            )
        elif record.kind == "X":
            _require(
                f["kd"].value in NONRASTER or "ct" in f,
                "artifact_contract", f"{id_}: a materialized raster needs a contract",
            )
            if "of" in f:
                output = doc.records[f["of"].id].fields
                _require(
                    f["kd"] == output["kd"] and f.get("ct") == output.get("ct"),
                    "candidate_output", f"{id_} must match its planned output's kind and contract",
                )
        elif record.kind == "V":
            task = doc.records[f["tk"].id].fields
            _require(id_ in _ids(task["vr"]), "verdict_owner", f"{id_} must remain in its task's verdict history")
            candidate = doc.records[f["xr"].id].fields
            output_ref = candidate.get("of")
            _require(output_ref is not None, "verdict_owner", f"{id_}: candidate has no planned output")
            output = doc.records[output_ref.id].fields
            _require(
                output["tk"] == f["tk"] and output_ref.id in _ids(task["op"]),
                "verdict_owner", f"{id_}: candidate belongs to another task",
            )
            try:
                datetime.fromisoformat(f["at"])
            except ValueError as error:
                raise PixlError("date", id_) from error
            if f["st"].value == "unavailable":
                _require(bool(f["wy"].strip()), "verdict_reason", f"{id_}: explain the unavailable inspection")
                _require(not f["ev"], "verdict_unavailable", f"{id_}: unavailable verdict must have no receipts")
            if f.get("ob", False):
                continue
            _require(
                f["rq"].id in _ids(output["rq"]),
                "verdict_requirement", f"{id_}: criterion is not required by this candidate's output",
            )
            key = (f["tk"].id, f["xr"].id, f["rq"].id)
            _require(key not in current_verdicts, "verdict_duplicate", f"{id_}: supersede the previous verdict first")
            current_verdicts[key] = record
            if f["st"].value != "unavailable":
                current = [e for e in f["ev"] if not doc.records[e.id].fields.get("ob", False)]
                criterion = doc.records[f["rq"].id].fields
                _require(bool(current), "verdict_evidence", f"{id_}: pass/fail needs current receipts")
                _require(
                    all(doc.records[e.id].fields["rs"] == f["st"]
                        and doc.records[e.id].fields["md"] == criterion["md"] for e in current),
                    "verdict_evidence", f"{id_}: receipts must match the verdict outcome and criterion mode",
                )
                _require(
                    scope(f["xr"].id) | scope(f["rq"].id) <= bound(current),
                    "verdict_proof", f"{id_}: receipts must bind the exact candidate, criterion and their semantic scopes",
                )

    for id_, record in doc.records.items():
        if record.kind != "T":
            continue
        f = record.fields
        _unique(f["op"], "output_owner", f"{id_}.op repeats a planned output")
        _unique(f["vr"], "verdict_owner", f"{id_}.vr repeats a verdict")
        for reference in f["op"]:
            _require(
                doc.records[reference.id].fields["tk"].id == id_,
                "output_owner", f"{id_}: {reference.id} belongs to another task",
            )
        for reference in f["vr"]:
            _require(
                doc.records[reference.id].fields["tk"].id == id_,
                "verdict_owner", f"{id_}: {reference.id} belongs to another task",
            )
        for choice_id in _output_choices(doc, f):
            _require(
                doc.records[choice_id].fields["pr"] == f["pr"],
                "task_project", f"{id_}: output choice {choice_id} belongs to another project",
            )
        nominees = {}
        for reference in f["ca"]:
            candidate = doc.records[reference.id].fields
            output = candidate.get("of")
            _require(
                output is not None and output.id in _ids(f["op"]),
                "candidate_output", f"{id_}: nominated {reference.id} must belong to a planned output",
            )
            _require(
                output.id not in nominees, "candidate_nomination",
                f"{id_}: only one candidate may be nominated for {output.id}",
            )
            nominees[output.id] = reference.id
        if f["st"].value in {"active", "done"}:
            reasons = _activation_blockers(doc, id_, scope, bound)
            if reasons:
                code, detail = reasons[0].split(": ", 1)
                raise PixlError(code, detail)
        if f["st"].value == "done":
            _require(
                bool(f["op"]) and set(nominees) == _ids(f["op"]),
                "completion", f"{id_}: every planned output needs one nominated candidate",
            )
            for output_id, candidate_id in nominees.items():
                for requirement in doc.records[output_id].fields["rq"]:
                    verdict = current_verdicts.get((id_, candidate_id, requirement.id))
                    status = verdict.fields["st"].value if verdict is not None else "unperformed"
                    _require(
                        status == "pass", "completion",
                        f"{id_}: {candidate_id} requirement {requirement.id} is {status}",
                    )
    return doc


def blockers(doc, task_id):
    """Return activation blockers for a task in an otherwise valid PX2 graph."""
    from .graph import proof_scope

    _require(task_id in doc.records and doc.records[task_id].kind == "T", "unknown_task", task_id)

    def bound(evidence, passing=False):
        covered = set()
        for reference in evidence:
            receipt = doc.records[reference.id].fields
            if not receipt.get("ob", False) and (not passing or receipt["rs"].value == "pass"):
                covered.update(binding["rf"].id for binding in receipt["bs"])
        return covered

    return _activation_blockers(doc, task_id, lambda id_: proof_scope(doc, [id_]), bound)


def report(doc):
    """Describe an already validated PX2 graph without changing its state.

    Requirements are shown for each current nominee and for retained older
    candidates. An absent current verdict is unperformed, never a pass.
    """
    intake, tasks, ready = [], [], []
    current = {
        (r.fields["tk"].id, r.fields["xr"].id, r.fields["rq"].id): r
        for r in doc.records.values() if r.kind == "V" and not r.fields.get("ob", False)
    }
    candidates = {}
    for id_, record in sorted(doc.records.items()):
        if record.kind == "X" and "of" in record.fields:
            candidates.setdefault(record.fields["of"].id, []).append(id_)

    def requirements(task_id, output, candidate_id):
        results = []
        for reference in output["rq"]:
            criterion = doc.records[reference.id].fields
            verdict = current.get((task_id, candidate_id, reference.id))
            results.append({
                "id": reference.id, "name": criterion["nm"],
                "check": criterion["ck"],
                "domain": criterion["dm"].value, "mode": criterion["md"].value,
                "status": verdict.fields["st"].value if verdict is not None else "unperformed",
                "verdict": verdict.id if verdict is not None else None,
                "reason": verdict.fields["wy"] if verdict is not None else None,
                "reviewer": verdict.fields["wh"].id if verdict is not None else None,
                "evidence": [e.id for e in verdict.fields["ev"]] if verdict is not None else [],
            })
        return results

    for id_, record in sorted(doc.records.items()):
        f = record.fields
        if record.kind == "I":
            intake.append({
                "id": id_, "project": f["pr"].id, "key": f["ky"],
                "status": f["st"].value, "value": to_data(f["vl"]),
                "sources": [s.id for s in f["so"]], "rationale": f["wy"],
            })
        elif record.kind == "T":
            reasons = blockers(doc, id_)
            if f["st"].value == "open" and not reasons:
                ready.append(id_)
            nominees = {doc.records[c.id].fields["of"].id: c.id for c in f["ca"]}
            outputs = []
            for reference in f["op"]:
                output = doc.records[reference.id].fields
                candidate_id = nominees.get(reference.id)
                outputs.append({
                    "id": reference.id, "name": output["nm"], "candidate": candidate_id,
                    "requirements": requirements(id_, output, candidate_id),
                    "candidates": [{
                        "id": other, "nominated": other == candidate_id,
                        "requirements": requirements(id_, output, other),
                    } for other in candidates.get(reference.id, [])],
                })
            tasks.append({
                "id": id_, "project": f["pr"].id, "phase": f["ph"].value,
                "state": f["st"].value, "blockers": reasons, "outputs": outputs,
            })
    return {"intake": intake, "tasks": tasks, "ready": ready}

"""Closed-schema validation, evidence integrity and deterministic graph queries."""

import hashlib
import json
import re
from datetime import datetime
from pathlib import Path
from urllib.parse import urlsplit

from .codec import Document, PixlError, Ref, Symbol, encode, record_hash

REGISTRY = json.loads(
    Path(__file__).with_name("registry.json").read_text(encoding="utf-8")
)
REGISTRIES = {
    1: REGISTRY,
    2: json.loads(
        Path(__file__).with_name("registry-v2.json").read_text(encoding="utf-8")
    ),
}
SHA = re.compile(r"[0-9a-f]{64}")


def refs(value):
    if isinstance(value, Ref):
        yield value.id
    elif isinstance(value, list):
        for child in value:
            yield from refs(child)
    elif isinstance(value, dict):
        for child in value.values():
            yield from refs(child)


def edges(doc):
    return {id_: set(refs(record.fields)) for id_, record in doc.records.items()}


def closure(adjacency, seeds):
    pending = list(seeds)
    found = set()
    while pending:
        id_ = pending.pop()
        if id_ not in found:
            found.add(id_)
            pending.extend(adjacency.get(id_, ()))
    return found


def proof_scope(doc, seeds, adjacency=None):
    """Bind design/method/art semantics, excluding mutable workflow and proof nodes."""
    adjacency = edges(doc) if adjacency is None else adjacency
    semantic = {
        id_: targets
        for id_, targets in adjacency.items()
        if doc.records[id_].kind not in ("EPTJNV" if doc.format == 2 else "EPTJN")
    }
    return set(
        closure(
            {id_: targets & semantic.keys() for id_, targets in semantic.items()},
            set(seeds) & semantic.keys(),
        )
    )


def confined(root, name):
    root = Path(root).resolve()
    path = Path(name)
    if path.is_absolute() or not name or "\\" in name or ":" in name:
        raise PixlError("path_escape", name)
    path = (root / path).resolve()
    if not path.is_relative_to(root) or path == root:
        raise PixlError("path_escape", name)
    return path


def file_hash(path):
    hasher = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            hasher.update(chunk)
    return hasher.hexdigest()


def _type(value, type_, doc):
    if type_ == "str":
        return type(value) is str
    if type_ == "sha":
        return type(value) is str and bool(SHA.fullmatch(value))
    if type_ == "int":
        return type(value) is int
    if type_ == "bool":
        return type(value) is bool
    if type_ == "map":
        return type(value) is dict
    if type_ == "value":
        return True
    if type_ in ("strings", "ints", "symbols"):
        typ = {"strings": str, "ints": int, "symbols": Symbol}[type_]
        return isinstance(value, list) and all(type(v) is typ for v in value)
    if type_.startswith("sym:"):
        return isinstance(value, Symbol) and value.value in type_[4:].split("|")
    if type_.startswith("refs:"):
        return isinstance(value, list) and all(
            _type(v, f"ref:{type_[5:]}", doc) for v in value
        )
    if type_.startswith("ref:"):
        return (
            isinstance(value, Ref)
            and value.id in doc.records
            and (type_[4:] == "*" or doc.records[value.id].kind == type_[4:])
        )
    raise PixlError("registry_type", type_)


def _require(condition, code, detail):
    if not condition:
        raise PixlError(code, detail)


def _dag(doc):
    tasks = {
        id_: set(refs(r.fields["dp"]))
        for id_, r in doc.records.items()
        if r.kind == "T"
    }
    # Kahn traversal avoids recursion limits for deep, otherwise valid plans.
    dependents = {id_: set() for id_ in tasks}
    for id_, needs in tasks.items():
        for needed in needs:
            dependents[needed].add(id_)
    pending = [id_ for id_, needs in tasks.items() if not needs]
    seen = 0
    while pending:
        id_ = pending.pop()
        seen += 1
        for other in dependents[id_]:
            tasks[other].remove(id_)
            if not tasks[other]:
                pending.append(other)
    _require(
        seen == len(tasks), "dependency_cycle", "task prerequisites must form a DAG"
    )


def validate(doc, root=None):
    encode(
        doc
    )  # Check wire-representable values and resource bounds, even for programmatic input.
    registry = REGISTRIES[doc.format]
    for id_, record in doc.records.items():
        _require(record.kind in registry["kinds"], "unknown_kind", record.kind)
        fields = dict(registry["common"], **registry["kinds"][record.kind]["fields"])
        for name in record.fields:
            _require(name in fields, "unknown_field", f"{id_}.{name}")
        for name, spec in fields.items():
            spec = {"type": spec} if isinstance(spec, str) else spec
            if name not in record.fields:
                _require(spec.get("optional", False), "missing_field", f"{id_}.{name}")
                continue
            _require(
                _type(record.fields[name], spec["type"], doc),
                "field_type",
                f"{id_}.{name}: {spec['type']}",
            )
        for target in refs(record.fields):
            _require(target in doc.records, "unresolved_ref", f"{id_} -> {target}")
    _dag(doc)
    adjacency = edges(doc)
    semantic = {
        id_
        for id_, record in doc.records.items()
        if record.kind not in ("EPTJNV" if doc.format == 2 else "EPTJN")
    }
    proof_edges = {
        id_: targets & semantic for id_, targets in adjacency.items() if id_ in semantic
    }
    scope_cache = {}

    def scope(id_):
        if id_ not in scope_cache:
            scope_cache[id_] = closure(proof_edges, [id_]) if id_ in semantic else set()
        return scope_cache[id_]

    def bound(evidence, passing=False):
        result = set()
        for reference in evidence:
            proof = doc.records[reference.id]
            if proof.fields.get("ob", False):
                continue
            if not passing or proof.fields["rs"].value == "pass":
                result.update(refs(proof.fields["bs"]))
        return result

    for id_, record in doc.records.items():
        f = record.fields
        if record.kind == "D":
            for key in ("wt", "wr", "wy", "rs", "pc"):
                _require(
                    bool(f[key])
                    and (not isinstance(f[key], str) or bool(f[key].strip())),
                    "decision_evidence",
                    f"{id_}.{key} is empty",
                )
            _require(
                scope(id_) <= bound(f["pc"]),
                "decision_proof",
                f"{id_}: proof must bind the decision, sources and semantic targets",
            )
        if record.kind == "K":
            for key in ("ap", "op", "ck", "so"):
                _require(bool(f[key]), "knowledge", f"{id_}.{key} is empty")
            if f.get("pc"):
                _require(
                    scope(id_) <= bound(f["pc"]),
                    "method_poc",
                    f"{id_}: proof must bind this method and its sources",
                )
        if record.kind == "R":
            _require(bool(f["so"]) and bool(f["vr"]), "runtime_source", id_)
        if record.kind == "C":
            _require(
                len(f["px"]) == 2 and all(0 < n <= 65536 for n in f["px"]),
                "dimensions",
                id_,
            )
            _require(
                all(
                    re.fullmatch(r"#[0-9A-Fa-f]{6}(?:[0-9A-Fa-f]{2})?", c)
                    for c in f["pl"]
                ),
                "palette",
                id_,
            )
        if record.kind == "S":
            _require(
                len(f["ln"]) in {0, 2}
                and (not f["ln"] or 1 <= f["ln"][0] <= f["ln"][1]),
                "source_range",
                id_,
            )
            _require(bool(f["ur"]), "source_uri", id_)
        if record.kind in ("S", "E"):
            try:
                datetime.fromisoformat(f["at"])
            except ValueError as error:
                raise PixlError("date", id_) from error
        if record.kind == "E":
            _require(
                isinstance(f["bs"], list) and bool(f["bs"]), "evidence_binding", id_
            )
            targets = set()
            for binding in f["bs"]:
                _require(
                    isinstance(binding, dict) and set(binding) == {"rf", "dg"},
                    "evidence_binding",
                    id_,
                )
                _require(
                    _type(binding["rf"], "ref:*", doc)
                    and _type(binding["dg"], "sha", doc),
                    "evidence_binding",
                    id_,
                )
                target = binding["rf"].id
                _require(
                    target not in targets and doc.records[target].kind != "E",
                    "evidence_binding",
                    f"{id_}: duplicate or recursive proof",
                )
                targets.add(target)
                if not f.get("ob", False):
                    _require(
                        record_hash(doc.records[target]) == binding["dg"],
                        "stale_evidence",
                        f"{id_} binds outdated {target}",
                    )
            for target in targets:
                if doc.records[target].kind == "X" and not f.get("ob", False):
                    dependencies = scope(target)
                    _require(
                        dependencies <= targets,
                        "evidence_context",
                        f"{id_}: bind artifact {target} and its full contract/reference closure",
                    )
        if record.kind == "T" and doc.format == 1:
            _require(bool(f["dc"]), "task_decision", id_)
            if f["st"].value in ("active", "done"):
                for method in f["kn"]:
                    proofs = doc.records[method.id].fields.get("pc", [])
                    _require(
                        scope(method.id) <= bound(proofs, passing=True),
                        "method_poc",
                        method.id,
                    )
            if f["st"].value == "done":
                _require(
                    bool(f["io"])
                    and all(
                        doc.records[d.id].fields["st"].value == "done" for d in f["dp"]
                    ),
                    "completion",
                    f"{id_}: artifacts/prerequisites",
                )
                passing = [
                    doc.records[e.id]
                    for e in f["ev"]
                    if doc.records[e.id].fields["rs"].value == "pass"
                    and not doc.records[e.id].fields.get("ob", False)
                ]
                needed = set(refs(f["io"]))
                covered = (
                    set().union(*(set(refs(e.fields["bs"])) for e in passing))
                    if passing
                    else set()
                )
                _require(
                    needed <= covered,
                    "completion",
                    f"{id_}: evidence must bind all artifacts",
                )
        if record.kind == "J":
            if f["si"].value in ("submitted", "running", "succeeded"):
                _require(bool(f["ri"]), "job_identity", id_)
            if f["si"].value == "succeeded":
                _require(bool(f["ev"]), "job_evidence", id_)
        if record.kind == "N":
            _require(0 <= f["rv"] <= doc.revision, "handoff_revision", id_)
        if root is not None and record.kind in ("S", "X", "E"):
            if record.kind == "S" and urlsplit(f["ur"]).scheme in ("https", "http"):
                continue
            path = confined(root, f["ur"])
            _require(path.is_file(), "file_missing", f"{id_}: {f['ur']}")
            _require(file_hash(path) == f["dg"], "file_hash", f"{id_}: {f['ur']}")
            if record.kind == "S" and f["ln"]:
                try:
                    count = len(path.read_text(encoding="utf-8").splitlines())
                except UnicodeError as error:
                    raise PixlError("source_encoding", id_) from error
                _require(f["ln"][1] <= count, "source_range", id_)
    if doc.format == 2:
        from . import delivery, families, jobs, lifecycle

        families.validate(doc)
        lifecycle.validate(doc, scope, bound)
        jobs.validate(doc, root)
        delivery.validate(doc, root)
    return doc


def ready(doc):
    validate(doc)
    if doc.format == 2:
        from . import lifecycle

        return sorted(
            id_
            for id_, r in doc.records.items()
            if r.kind == "T"
            and r.fields["st"].value == "open"
            and not lifecycle.blockers(doc, id_)
        )
    return sorted(
        id_
        for id_, r in doc.records.items()
        if r.kind == "T"
        and r.fields["st"].value == "open"
        and all(doc.records[d.id].fields["st"].value == "done" for d in r.fields["dp"])
    )


def impact(doc, id_):
    validate(doc)
    _require(id_ in doc.records, "unknown_record", id_)
    reverse = {key: set() for key in doc.records}
    for source, targets in edges(doc).items():
        for target in targets:
            reverse[target].add(source)
    return sorted(closure(reverse, [id_]))


def context(doc, focus, budget=None):
    validate(doc)
    _require(focus in doc.records, "unknown_record", focus)
    seeds = {focus} | {id_ for id_, r in doc.records.items() if r.kind == "P"}
    for id_, r in doc.records.items():
        if r.kind in ("J", "N") and focus in set(refs(r.fields)):
            seeds.add(id_)
    selected = closure(edges(doc), seeds)
    packet = Document(
        doc.revision,
        {id_: doc.records[id_] for id_ in sorted(selected)},
        format=doc.format,
    )
    required = len(encode(packet))
    if budget is not None:
        _require(
            type(budget) is int and budget > 0,
            "context_budget",
            "budget must be a positive byte count",
        )
        _require(
            required <= budget,
            "context_budget",
            f"required={required}, budget={budget}; required closure was not truncated",
        )
    return packet

"""Shared local operation surface used by CLI and MCP."""

import hashlib
import json
import os
from pathlib import Path

from . import assets, catalog, codec, graph, jobs, store
from .codec import PixlError


def resource_root():
    if plugin := os.environ.get("PIXL_PLUGIN_ROOT"):
        return Path(plugin).resolve() / "resources"
    packaged = Path(__file__).with_name("resources")
    if packaged.is_dir():
        return packaged
    return Path(__file__).resolve().parent.parent


def source_slice(path, expected, start, end, budget=16384):
    data = Path(path).read_bytes()
    if hashlib.sha256(data).hexdigest() != expected:
        raise PixlError(
            "source_hash", "source changed; reindex and reassess dependent claims"
        )
    if any(type(n) is not int for n in (start, end, budget)) or budget < 1:
        raise PixlError(
            "source_range", "integer line bounds and positive byte budget required"
        )
    try:
        lines = data.decode("utf-8-sig").splitlines(keepends=True)
    except UnicodeError as error:
        raise PixlError("source_encoding", str(path)) from error
    if not 1 <= start <= end <= len(lines):
        raise PixlError("source_range", f"source contains {len(lines)} lines")
    text = "".join(lines[start - 1 : end])
    size = len(text.encode("utf-8"))
    if size > budget:
        raise PixlError(
            "source_budget", f"required={size}, budget={budget}; narrow the line range"
        )
    return {"text": text, "sha256": expected, "start": start, "end": end, "bytes": size}


def load_document(path):
    try:
        if Path(path).stat().st_size > codec.MAX_BYTES:
            raise PixlError("input_size", "document exceeds 16 MiB")
        return codec.parse(Path(path).read_bytes())
    except OSError as error:
        raise PixlError("file_read", str(path)) from error


def _reject_constant(value):
    raise PixlError("json", "nonfinite number")


def read_json(path):
    try:
        return json.loads(
            Path(path).read_text(encoding="utf-8"),
            parse_constant=_reject_constant,
        )
    except (OSError, ValueError) as error:
        raise PixlError("json_read", str(path)) from error


def knowledge(method=None):
    data = read_json(resource_root() / "knowledge" / "pixel-art.json")
    if method:
        if matches := [m for m in data["methods"] if m["id"] == method]:
            return matches[0]
        else:
            raise PixlError("unknown_method", method)
    return {
        "version": data["version"],
        "methods": [
            {"id": m["id"], "title": m["title"], "applies_to": m["applies_to"]}
            for m in data["methods"]
        ],
    }


def source_inventory(root=None):
    from .sources import load_inventory

    selected = resource_root() if root is None else Path(root).resolve()
    return dict(
        load_inventory(selected),
        root=str(selected),
        files_verified=True,
        authority="Declared source revisions; local byte identity verified, not external truth.",
    )


def from_data(value):
    if isinstance(value, list):
        return [from_data(v) for v in value]
    if isinstance(value, dict):
        if set(value) == {"$ref"}:
            return codec.Ref(value["$ref"])
        if set(value) == {"$symbol"}:
            return codec.Symbol(value["$symbol"])
        return {k: from_data(v) for k, v in value.items()}
    return value


def capability_index(name=None):
    from .platform import capabilities

    data = capabilities(name)
    if name is not None:
        return data
    if not isinstance(data, dict):
        raise PixlError("platform_catalog", "capability catalog must be an object")
    return {
        "version": data.get("version"),
        "retrieved_at": data.get("retrieved_at"),
        "source": data.get("source"),
        "live_discovery": False,
        "tools": [
            {
                k: row.get(k)
                for k in ("name", "category", "effect", "required", "poll_tool")
            }
            for row in data["tools"]
        ],
    }


def from_json(data):
    if (
        not isinstance(data, dict)
        or set(data) not in ({"revision", "records"}, {"format", "revision", "records"})
        or not isinstance(data["records"], list)
    ):
        raise PixlError(
            "document_shape", "expected {revision, records:[{id,kind,fields}]}"
        )
    doc = codec.Document(data["revision"], format=data.get("format", 1))
    for row in data["records"]:
        if not isinstance(row, dict) or set(row) != {"id", "kind", "fields"}:
            raise PixlError(
                "record_shape", "exact id/kind/fields required; duplicate IDs forbidden"
            )
        row_id = row["id"]
        row_kind = row["kind"]
        row_fields = row["fields"]
        if (
            not isinstance(row_id, str)
            or not isinstance(row_kind, str)
            or row_id in doc.records
        ):
            raise PixlError(
                "record_shape", "exact id/kind/fields required; duplicate IDs forbidden"
            )
        if not isinstance(row_fields, dict):
            raise PixlError("record_shape", "record fields must be a map")
        fields = from_data(row_fields)
        if not isinstance(fields, dict):
            raise PixlError("record_shape", "decoded record fields must be a map")
        doc.records[row_id] = codec.Record(row_id, row_kind, fields)
    graph.validate(doc)
    return doc


def inspect_document(path, root=None):
    doc = load_document(path)
    graph.validate(doc, root)
    return {
        "valid": True,
        "format": doc.format,
        "revision": doc.revision,
        "hash": codec.digest(doc),
        "records": len(doc.records),
        "files_verified": root is not None,
        "record_hashes": {
            id_: codec.record_hash(r) for id_, r in sorted(doc.records.items())
        },
    }


def workflow(path, root=None):
    from . import lifecycle

    doc = load_document(path)
    graph.validate(doc, root)
    if doc.format != 2:
        raise PixlError(
            "lifecycle_format",
            "workflow requires PX2; PX1 state retains its original rules",
        )
    return dict(
        lifecycle.report(doc),
        format=2,
        revision=doc.revision,
        hash=codec.digest(doc),
        files_verified=root is not None,
    )


JOB_REQUEST_FIELDS = (
    "provider",
    "tool",
    "arguments",
    "schema",
    "discovery",
    "authorization",
)


def job_prepare(folder, expected, job_id, task_id, outputs, request, root=None):
    """Validate the request envelope before publishing durable provider intent."""
    if not isinstance(request, dict) or set(request) != set(JOB_REQUEST_FIELDS):
        raise PixlError(
            "job_request",
            "request must contain exactly provider, tool, arguments, schema, discovery and authorization",
        )
    return jobs.prepare(
        folder,
        expected,
        job_id,
        task_id,
        outputs,
        **request,
        root=root,
    )


def job_report(path, root):
    return jobs.report(load_document(path), root)


def family_report(path, root, output_id=None):
    """Verify retained family files and describe the current saved selection."""
    from . import delivery

    return delivery.report(load_document(path), root, output_id)


def call(name, args, root):
    root = Path(root).resolve()

    def path(key):
        return graph.confined(root, args[key])

    if name == "pixl_validate":
        return inspect_document(path("path"), root)
    if name in ("pixl_context", "pixl_ready", "pixl_impact"):
        doc = load_document(path("path"))
        graph.validate(doc, root)
        if name == "pixl_ready":
            return {"ready": graph.ready(doc), "hash": codec.digest(doc)}
        if name == "pixl_impact":
            return {"affected": graph.impact(doc, args["id"])}
        packet = graph.context(doc, args["focus"], args.get("budget"))
        wire = codec.encode(packet)
        return {
            "wire": wire.decode("utf-8"),
            "bytes": len(wire),
            "hash": codec.digest(doc),
            "revision": doc.revision,
        }
    if name == "pixl_init":
        return store.initialize(
            path("store"), root=root, name=args.get("name", "PIXL project")
        )
    if name == "pixl_intake":
        return store.initialize(
            path("store"),
            doc=store.intake_project(
                args.get("name", "PIXL project"), args.get("brief", "")
            ),
            root=root,
        )
    if name == "pixl_workflow":
        return workflow(path("path"), root)
    if name == "pixl_family":
        return family_report(path("path"), root, args.get("output"))
    if name == "pixl_family_snapshot":
        from . import delivery

        return delivery.snapshot(
            path("store"),
            args["expect"],
            args["output_id"],
            args["candidate_id"],
            root,
        )
    if name == "pixl_job_prepare":
        return job_prepare(
            path("store"),
            args["expect"],
            args["job_id"],
            args["task_id"],
            args["outputs"],
            {key: args[key] for key in JOB_REQUEST_FIELDS},
            root,
        )
    if name == "pixl_job_dispatch":
